fn resolve_ref(git_dir: &Path, ref_path: &str) -> Result<String, GitInfoError> {
    // First, try loose ref.
    let loose_ref_path = git_dir.join(ref_path);
    if loose_ref_path.exists() {
        let commit = fs_err::read_to_string(loose_ref_path)?;
        return Ok(commit.trim().to_string());
    }

    // Then, try packed refs.
    let packed_refs_path = git_dir.join("packed-refs");
    if packed_refs_path.exists() {
        let packed_refs = fs_err::read_to_string(packed_refs_path)?;
        for line in packed_refs.lines() {
            if line.starts_with('#') || line.trim().is_empty() {
                continue;
            }
            // Format: <commit> <ref>
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() < 2 {
                continue;
            }
            let commit_hash = parts[0];
            let ref_name = parts[1];
            if ref_name == ref_path {
                return Ok(commit_hash.to_string());
            }
        }
    }

    Err(GitInfoError::MissingRef(git_dir.to_path_buf(), ref_path.to_string()))
}
